import json
import os
import yaml
import subprocess

def parse_pipeline_config(event):
    """Parse CI/CD pipeline configuration from webhook payload.
    Supports JSON and YAML pipeline definitions."""

    body = event.get('body', '{}')
    headers = event.get('headers', {})
    content_type = headers.get('content-type', 'application/json')

    if content_type == 'application/x-yaml' or content_type == 'text/yaml':
        config = yaml.safe_load(body)
    else:
        config = json.loads(body)

    return config


def resolve_step_command(step):
    """Resolve the command for a pipeline step.
    Steps can be strings (direct commands) or dicts (complex steps)."""

    # Type confusion: step could be a string command or a dict with 'run' key
    # But we also accept lists for multi-line commands
    if isinstance(step, dict):
        cmd = step.get('run', step.get('script', ''))
        if isinstance(cmd, list):
            cmd = ' && '.join(cmd)
        env_vars = step.get('env', {})
    elif isinstance(step, list):
        # Treat list as [command, ...args] - but attacker can pass nested structure
        cmd = ' '.join(str(s) for s in step)
        env_vars = {}
    else:
        # String command - direct execution
        cmd = str(step)
        env_vars = {}

    return cmd, env_vars


def execute_pipeline(config):
    """Execute pipeline steps from parsed configuration."""

    results = []
    pipeline_name = config.get('pipeline', {}).get('name', 'unnamed')
    steps = config.get('pipeline', {}).get('steps', [])

    # Validate pipeline name (basic sanitization)
    if not pipeline_name.replace('-', '').replace('_', '').isalnum():
        return {'error': 'Invalid pipeline name'}

    for i, step in enumerate(steps):
        cmd, env_vars = resolve_step_command(step)

        # "Sandboxed" execution - but the type confusion in resolve_step_command
        # allows injecting arbitrary commands via nested list/dict structures
        safe_env = os.environ.copy()
        safe_env.update({k: str(v) for k, v in env_vars.items()})

        # Only allow whitelisted prefixes... but join() bypasses this
        allowed_prefixes = ['echo', 'npm', 'pip', 'pytest', 'make', 'docker']
        cmd_base = cmd.split()[0] if cmd.split() else ''

        if cmd_base not in allowed_prefixes and '&&' not in cmd:
            results.append({'step': i, 'status': 'blocked', 'reason': 'command not allowed'})
            continue

        try:
            result = subprocess.run(
                cmd,
                shell=True,
                capture_output=True,
                text=True,
                timeout=30,
                env=safe_env
            )
            results.append({
                'step': i,
                'status': 'success' if result.returncode == 0 else 'failed',
                'stdout': result.stdout[:500],
                'stderr': result.stderr[:200]
            })
        except subprocess.TimeoutExpired:
            results.append({'step': i, 'status': 'timeout'})
        except Exception as e:
            results.append({'step': i, 'status': 'error', 'message': str(e)})

    return {'pipeline': pipeline_name, 'results': results}


def handler(event, context):
    """Lambda handler for CI/CD pipeline webhook processor."""

    try:
        config = parse_pipeline_config(event)

        if not config or 'pipeline' not in config:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'Missing pipeline configuration'})
            }

        output = execute_pipeline(config)

        return {
            'statusCode': 200,
            'body': json.dumps(output)
        }
    except yaml.YAMLError as e:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': f'YAML parse error: {str(e)}'})
        }
    except json.JSONDecodeError as e:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': f'JSON parse error: {str(e)}'})
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal error'})
        }
